package com.themajesty.toplu;
import android.app.*;import android.os.*;import android.provider.Settings;import android.content.*;import android.net.*;import android.widget.*;
public class MainActivity extends Activity{public void onCreate(Bundle b){super.onCreate(b);LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(40,100,40,20);TextView t=new TextView(this);t.setText("THE MAJESTY\nTOPLU GÖRSEL v2\n\nÖnce erişilebilirliği, sonra turuncu düğme iznini aç.");t.setTextSize(25);l.addView(t);Button a=new Button(this);a.setText("ERİŞİLEBİLİRLİĞİ AÇ");a.setOnClickListener(v->startActivity(new Intent(Settings.ACTION_ACCESSIBILITY_SETTINGS)));l.addView(a);Button o=new Button(this);o.setText("TURUNCU DÜĞME İZNİ");o.setOnClickListener(v->startActivity(new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION,Uri.parse("package:"+getPackageName()))));l.addView(o);setContentView(l);}}